import { getCookie, verifySession } from './lib/auth.js';

const ADMIN_PATH = '/manage-dpv-7f3a9c2e';

function adminHtml() {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DESIGN PERFUME VENDOR · Private Admin</title><style>body{margin:0;background:#eef0f3;color:#111214;font:14px Arial,sans-serif}.wrap{max-width:860px;margin:0 auto;padding:30px 16px 60px}.card{padding:20px;margin-top:14px;background:#fff;border:1px solid #e3e5e8;border-radius:12px;box-shadow:0 5px 18px #11121412}h1{font-size:34px;margin:0 0 8px}h2{font-size:20px;margin:0}.muted{color:#64676d;font-size:12px;line-height:1.5}.row{padding:14px 0;border-bottom:1px solid #e3e5e8}.row:last-child{border:0}.head{display:flex;justify-content:space-between;align-items:center}label{display:block;margin:10px 0 6px;color:#5b5e63;font-size:11px;font-weight:700}input,textarea,select{width:100%;padding:10px;box-sizing:border-box;border:1px solid #e3e5e8;border-radius:8px;background:#fff;font:13px Arial}button{border:0;border-radius:8px;padding:11px 15px;background:#111214;color:#fff;font-weight:700;cursor:pointer}.secondary{background:#fff;color:#111214;border:1px solid #e3e5e8}.actions{display:flex;gap:8px;margin-top:14px}.hidden{display:none}.status{font-size:12px;color:#4c9a4e;margin-top:10px}.danger{color:#a44a44}.login{max-width:390px;margin:80px auto}.remove{background:#fff4f2;color:#a44a44;border:1px solid #ecc7c2;font-size:11px;padding:6px 9px}.inline{display:flex;align-items:center;gap:7px;margin:12px 0 4px}.inline input{width:auto}</style></head><body><main class="wrap"><section id="login" class="card login"><h1>Private Admin</h1><p class="muted">Sign in to manage vendor contacts and FAQ content.</p><label>Username</label><input id="username" autocomplete="username"><label>Password</label><input id="password" type="password" autocomplete="current-password"><div class="actions"><button id="loginBtn">Sign in</button></div><p id="loginStatus" class="status danger"></p></section><section id="app" class="hidden"><h1>Campaign settings</h1><p class="muted">Protected route: ${ADMIN_PATH}</p><div class="card"><h2>Appearance</h2><label>Page background image URL</label><input id="bgImage" placeholder="https://... (leave empty for the default color)"><label>Hero section background image URL</label><input id="heroImage" placeholder="https://... (leave empty for no hero image)"><p class="muted">The page background sits behind everything; the hero image is a rounded card behind the avatar, title, and description. Both get a soft light overlay.</p></div><div class="card"><div class="head"><h2>Contact channels</h2><button id="addChannel">+ Add channel</button></div><p class="muted">WhatsApp uses shared round-robin numbers; other channels use a direct URL. Icons are assigned automatically per platform.</p><div id="channels"></div></div><div class="card"><div class="head"><h2>Menu cards</h2><button id="addMenu">+ Add menu card</button></div><p class="muted">Cards between the contact channels and FAQ. Icon is auto-detected from the URL, or force one: tiktok, instagram, facebook, telegram, email, website, shop, link.</p><div id="menuCards"></div></div><div class="card"><div class="head"><h2>FAQ</h2><button id="addFaq">+ Add FAQ</button></div><div id="faqs"></div></div><div class="card"><h2>TikTok tracking</h2><label>Pixel ID</label><input id="pixelId"><label>Event Set ID</label><input id="eventSetId"><p class="muted">Events: PageView (auto), ViewContent (landing view), Contact (WhatsApp click, also sent server-side through the Events API when the TIKTOK_EVENTS_API_TOKEN secret is set).</p><div class="actions"><button id="saveBtn">Save all changes</button><button class="secondary" id="logoutBtn">Sign out</button></div><p id="status" class="status"></p></div></section></main><script>
let config={contactChannels:[],menuCards:[],faq:[],tiktokPixelId:'',eventSetId:'',appearance:{backgroundImage:''}};const $=s=>document.querySelector('#'+s),esc=v=>String(v||'').replace(/[&<>\\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\"':'&quot;',"'":'&#39;'}[c]));const TYPES=[['whatsapp','WhatsApp'],['tiktok','TikTok'],['instagram','Instagram'],['facebook','Facebook'],['telegram','Telegram'],['email','Email'],['website','Website']];function setStatus(t,e=false){$('status').textContent=t;$('status').className=e?'status danger':'status'}function render(){ $('channels').innerHTML=config.contactChannels.map((c,i)=>'<div class="row channel" data-i="'+i+'"><div class="head"><strong>Channel '+(i+1)+'</strong><button class="remove" data-rm-c="'+i+'">Remove</button></div><label>Type</label><select class="type">'+TYPES.map(t=>'<option value="'+t[0]+'" '+(c.type===t[0]?'selected':'')+'>'+t[1]+'</option>').join('')+'</select><label>Label</label><input class="label" value="'+esc(c.label)+'"><label>Subtitle</label><input class="subtitle" value="'+esc(c.subtitle)+'"><label>Direct URL</label><input class="url" value="'+esc(c.url)+'" placeholder="https://... or mailto:..."><label>WhatsApp numbers</label><textarea class="numbers" rows="3">'+esc((c.numbers||[]).join('\\n'))+'</textarea><label>Card background image URL (optional)</label><input class="bg" value="'+esc(c.backgroundImage)+'" placeholder="https://... (leave empty for white card)"><label class="inline"><input type="checkbox" class="enabled" '+(c.enabled!==false?'checked':'')+'> Active</label></div>').join('');$('menuCards').innerHTML=(config.menuCards||[]).map((m,i)=>'<div class="row menu" data-i="'+i+'"><div class="head"><strong>Menu card '+(i+1)+'</strong><button class="remove" data-rm-m="'+i+'">Remove</button></div><label>Label</label><input class="label" value="'+esc(m.label)+'"><label>Subtitle</label><input class="subtitle" value="'+esc(m.subtitle)+'"><label>URL</label><input class="url" value="'+esc(m.url)+'" placeholder="https://..."><label>Icon keyword (optional)</label><input class="icon" value="'+esc(m.icon)+'" placeholder="Auto from URL · tiktok, instagram, facebook, telegram, email, website, shop, link"><label>Card background image URL (optional)</label><input class="bg" value="'+esc(m.backgroundImage)+'" placeholder="https://... (leave empty for white card)"><label class="inline"><input type="checkbox" class="enabled" '+(m.enabled!==false?'checked':'')+'> Active</label></div>').join('');$('faqs').innerHTML=config.faq.map((f,i)=>'<div class="row faq" data-i="'+i+'"><div class="head"><strong>FAQ '+(i+1)+'</strong><button class="remove" data-rm-f="'+i+'">Remove</button></div><label>Question</label><input class="q" value="'+esc(f.q)+'"><label>Answer</label><textarea class="a" rows="3">'+esc(f.a)+'</textarea></div>').join('');$('bgImage').value=(config.appearance&&config.appearance.backgroundImage)||'';$('heroImage').value=(config.appearance&&config.appearance.heroImage)||'';$('pixelId').value=config.tiktokPixelId||'';$('eventSetId').value=config.eventSetId||'';document.querySelectorAll('[data-rm-c]').forEach(b=>b.onclick=()=>{config.contactChannels.splice(+b.dataset.rmC,1);render()});document.querySelectorAll('[data-rm-m]').forEach(b=>b.onclick=()=>{config.menuCards.splice(+b.dataset.rmM,1);render()});document.querySelectorAll('[data-rm-f]').forEach(b=>b.onclick=()=>{config.faq.splice(+b.dataset.rmF,1);render()});document.querySelectorAll('.channel').forEach(r=>{const t=r.querySelector('.type'),u=r.querySelector('.url'),ul=u.previousElementSibling,n=r.querySelector('.numbers'),nl=n.previousElementSibling;const up=()=>{const w=t.value==='whatsapp';u.hidden=w;ul.hidden=w;n.hidden=!w;nl.hidden=!w};t.onchange=up;up()})}async function load(){const r=await fetch('/api/admin/config');if(r.status===401)return;config=await r.json();config.appearance=config.appearance||{};config.menuCards=config.menuCards||[];render();$('login').classList.add('hidden');$('app').classList.remove('hidden')}$('loginBtn').onclick=async()=>{const r=await fetch('/api/admin/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:$('username').value,password:$('password').value})});if(!r.ok){$('loginStatus').textContent='Invalid credentials';return}load()};$('addChannel').onclick=()=>{config.contactChannels.push({id:'channel-'+Date.now(),type:'tiktok',label:'New social channel',subtitle:'Follow us',enabled:true,url:'',numbers:[],backgroundImage:''});render()};$('addMenu').onclick=()=>{config.menuCards.push({id:'menu-'+Date.now(),label:'New menu card',subtitle:'Open link',url:'',icon:'',backgroundImage:'',enabled:true});render()};$('addFaq').onclick=()=>{config.faq.push({q:'New question',a:'Add an answer.'});render()};$('saveBtn').onclick=async()=>{const channels=[...document.querySelectorAll('.channel')].map((r,i)=>({id:config.contactChannels[i]?.id||('channel-'+Date.now()+i),type:r.querySelector('.type').value,label:r.querySelector('.label').value,subtitle:r.querySelector('.subtitle').value,enabled:r.querySelector('.enabled').checked,url:r.querySelector('.url').value,numbers:r.querySelector('.numbers').value.split(/\\n|,|\\s+/).filter(Boolean),backgroundImage:r.querySelector('.bg').value}));const menus=[...document.querySelectorAll('.menu')].map((r,i)=>({id:config.menuCards[i]?.id||('menu-'+Date.now()+i),label:r.querySelector('.label').value,subtitle:r.querySelector('.subtitle').value,url:r.querySelector('.url').value,icon:r.querySelector('.icon').value,backgroundImage:r.querySelector('.bg').value,enabled:r.querySelector('.enabled').checked})).filter(m=>m.label||m.url);const faqs=[...document.querySelectorAll('.faq')].map(r=>({q:r.querySelector('.q').value,a:r.querySelector('.a').value})).filter(f=>f.q||f.a);const r=await fetch('/api/admin/config',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({tiktokPixelId:$('pixelId').value,eventSetId:$('eventSetId').value,appearance:{backgroundImage:$('bgImage').value,heroImage:$('heroImage').value},contactChannels:channels,menuCards:menus,faq:faqs})});setStatus(r.ok?'Saved successfully':'Save failed',!r.ok)};$('logoutBtn').onclick=()=>{document.cookie='dpv_session=; Max-Age=0; Path=/';location.reload()};load();</script></body></html>`;
}

export async function onRequestGet({ request, env }) { const valid = await verifySession(getCookie(request, 'dpv_session'), env.SESSION_SECRET || env.ADMIN_PASSWORD || ''); return new Response(adminHtml(), { status: 200, headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' } }); }
